insert into public.events (id, title, description, date, location, image, status, "volunteersNeeded", "volunteersJoined") values ('evt-001', '{"en":"Community Seva Day","hi":"सामुदायिक सेवा दिवस"}'::jsonb, '{"en":"A day dedicated to serving our community through food distribution, cleanliness drives, and connecting with people who need support.","hi":"भोजन वितरण, स्वच्छता अभियान और ज़रूरतमंदों से जुड़ने के माध्यम से समुदाय की सेवा को समर्पित दिन।"}'::jsonb, '2026-08-15', '{"en":"Main Community Ground","hi":"मुख्य सामुदायिक मैदान"}'::jsonb, '/assets/images/community-support.jpg', 'upcoming', 50, 32) on conflict (id) do nothing;
insert into public.events (id, title, description, date, location, image, status, "volunteersNeeded", "volunteersJoined") values ('evt-002', '{"en":"Seva & Nature Initiative","hi":"सेवा और प्रकृति पहल"}'::jsonb, '{"en":"A combined initiative focusing on tree plantation, river clean-up, and environmental awareness in our neighborhood.","hi":"हमारे मोहल्ले में वृक्षारोपण, नदी सफ़ाई और पर्यावरण जागरूकता पर केंद्रित संयुक्त पहल।"}'::jsonb, '2026-08-26', '{"en":"River Bank & Community Park","hi":"नदी तट और सामुदायिक पार्क"}'::jsonb, '/assets/images/nature-seva.jpg', 'upcoming', 40, 18) on conflict (id) do nothing;
insert into public.events (id, title, description, date, location, image, status, "volunteersNeeded", "volunteersJoined") values ('evt-003', '{"en":"Winter Food Seva","hi":"शीतकालीन भोजन सेवा"}'::jsonb, '{"en":"Preparing and distributing warm meals and blankets to those in need during the cold winter months.","hi":"ठंडे शीतकालीन महीनों में ज़रूरतमंदों के लिए गर्म भोजन और कंबल तैयार कर वितरित करना।"}'::jsonb, '2026-12-15', '{"en":"Multiple Locations","hi":"विभिन्न स्थान"}'::jsonb, '/assets/images/food-seva.jpg', 'upcoming', 60, 10) on conflict (id) do nothing;
insert into public.events (id, title, description, date, location, image, status, "volunteersNeeded", "volunteersJoined") values ('evt-004', '{"en":"Republic Day Special Seva","hi":"गणतंत्र दिवस विशेष सेवा"}'::jsonb, '{"en":"A special food distribution and community gathering to celebrate Republic Day with service.","hi":"गणतंत्र दिवस को सेवा के साथ मनाने हेतु विशेष भोजन वितरण और सामुदायिक सभा।"}'::jsonb, '2026-01-26', '{"en":"Main Community Ground","hi":"मुख्य सामुदायिक मैदान"}'::jsonb, '/assets/images/community-support.jpg', 'past', null, 50) on conflict (id) do nothing;
insert into public.events (id, title, description, date, location, image, status, "volunteersNeeded", "volunteersJoined") values ('evt-005', '{"en":"World Environment Day Plantation","hi":"विश्व पर्यावरण दिवस वृक्षारोपण"}'::jsonb, '{"en":"Planted 100 trees and conducted environmental awareness activities with local schools.","hi":"स्थानीय स्कूलों के साथ 100 पेड़ लगाए और पर्यावरण जागरूकता गतिविधियाँ आयोजित कीं।"}'::jsonb, '2026-06-05', '{"en":"Community Park","hi":"सामुदायिक पार्क"}'::jsonb, '/assets/images/nature-seva.jpg', 'past', null, 45) on conflict (id) do nothing;
insert into public.events (id, title, description, date, location, image, status, "volunteersNeeded", "volunteersJoined") values ('evt-006', '{"en":"Summer Water Seva Camp","hi":"ग्रीष्मकालीन जल सेवा शिविर"}'::jsonb, '{"en":"Set up water distribution points across the city to help people and animals during extreme heat.","hi":"तेज़ गर्मी के दौरान लोगों और जानवरों की मदद के लिए पूरे शहर में जल वितरण केंद्र स्थापित किए।"}'::jsonb, '2026-05-20', '{"en":"Citywide","hi":"पूरे शहर में"}'::jsonb, '/assets/images/food-seva.jpg', 'past', null, 30) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('food-dist-001', '{"en":"Community Food Distribution","hi":"सामुदायिक भोजन वितरण"}'::jsonb, '{"en":"Distributed freshly cooked meals to over 100 families in the local neighborhood.","hi":"स्थानीय मोहल्ले में 100 से अधिक परिवारों को ताज़ा पका भोजन वितरित किया।"}'::jsonb, '{"en":"Our volunteers gathered early in the morning to prepare fresh, nutritious meals for families in need. We distributed food packets across three different localities, reaching over 100 families. The joy on people''s faces reminded us why seva matters.","hi":"हमारे स्वयंसेवकों ने ज़रूरतमंद परिवारों के लिए ताज़ा और पौष्टिक भोजन तैयार करने के लिए सुबह जल्दी एकत्र हुए। हमने तीन अलग-अलग मोहल्लों में भोजन पैकेट वितरित किए और 100 से अधिक परिवारों तक पहुँचे। लोगों के चेहरों पर खुशी ने हमें याद दिलाया कि सेवा क्यों मायने रखती है।"}'::jsonb, '2026-01-15', '{"en":"Sector 12, Local Community Area","hi":"सेक्टर 12, स्थानीय सामुदायिक क्षेत्र"}'::jsonb, 'food-seva', '["/assets/images/food-seva.jpg"]'::jsonb, 25, true) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('tree-plant-001', '{"en":"Tree Plantation Drive","hi":"वृक्षारोपण अभियान"}'::jsonb, '{"en":"Planted 200+ saplings along the community park and roadside areas.","hi":"सामुदायिक पार्क और सड़क किनारों पर 200+ पौधे लगाए।"}'::jsonb, '{"en":"In collaboration with local authorities, we organized a large-scale tree plantation drive. Volunteers of all ages came together to plant over 200 saplings. Each tree represents our commitment to a greener future.","hi":"स्थानीय प्रशासन के सहयोग से हमने एक वृहद वृक्षारोपण अभियान आयोजित किया। हर उम्र के स्वयंसेवकों ने मिलकर 200 से अधिक पौधे लगाए। हर वृक्ष हमारी हरित भविष्य के प्रति प्रतिबद्धता दर्शाता है।"}'::jsonb, '2026-02-20', '{"en":"Community Park & Main Road","hi":"सामुदायिक पार्क और मुख्य सड़क"}'::jsonb, 'nature', '["/assets/images/nature-seva.jpg"]'::jsonb, 40, true) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('animal-feed-001', '{"en":"Stray Animal Feeding","hi":"आवारा पशुओं को भोजन"}'::jsonb, '{"en":"Provided food and water to stray dogs, cats, and birds across the neighborhood.","hi":"मोहल्ले भर में आवारा कुत्तों, बिल्लियों और पक्षियों को भोजन और पानी उपलब्ध कराया।"}'::jsonb, '{"en":"Our animal care volunteers visited multiple areas to feed stray dogs and cats. We also set up water bowls at various locations to ensure animals have access to clean drinking water during the warm season.","hi":"हमारे पशु देखभाल स्वयंसेवक आवारा कुत्तों और बिल्लियों को खिलाने के लिए कई क्षेत्रों में गए। हमने विभिन्न स्थानों पर पानी के कटोरे भी रखे ताकि गर्म मौसम में जानवरों को साफ़ पीने का पानी मिलता रहे।"}'::jsonb, '2026-03-10', '{"en":"Multiple Neighborhood Locations","hi":"मोहल्ले के विभिन्न स्थान"}'::jsonb, 'animals', '["/assets/images/animal-care.jpg"]'::jsonb, 15, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('water-seva-001', '{"en":"Summer Water Distribution","hi":"ग्रीष्मकालीन जल वितरण"}'::jsonb, '{"en":"Distributed drinking water to daily wage workers and travelers during peak summer.","hi":"तेज़ गर्मी में दिहाड़ी मज़दूरों और यात्रियों को पीने का पानी वितरित किया।"}'::jsonb, '{"en":"During the peak of summer, we set up water distribution points at busy intersections and construction sites. Our volunteers distributed cold drinking water to daily wage workers, auto drivers, and travelers throughout the day.","hi":"गर्मी के चरम के दौरान हमने व्यस्त चौराहों और निर्माण स्थलों पर जल वितरण केंद्र स्थापित किए। हमारे स्वयंसेवकों ने पूरे दिन दिहाड़ी मज़दूरों, ऑटो चालकों और यात्रियों को ठंडा पीने का पानी वितरित किया।"}'::jsonb, '2026-04-05', '{"en":"City Center & Construction Sites","hi":"शहर केंद्र और निर्माण स्थल"}'::jsonb, 'food-seva', '["/assets/images/food-seva.jpg"]'::jsonb, 20, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('clean-drive-001', '{"en":"Neighborhood Cleanliness Drive","hi":"मोहल्ला स्वच्छता अभियान"}'::jsonb, '{"en":"Organized a cleanliness campaign covering 5 blocks in the community.","hi":"समुदाय के 5 ब्लॉकों में स्वच्छता अभियान चलाया।"}'::jsonb, '{"en":"We organized a comprehensive cleanliness drive covering 5 blocks in our community. Volunteers collected waste, cleaned public spaces, and educated residents about proper waste disposal and recycling practices.","hi":"हमने समुदाय के 5 ब्लॉकों में एक व्यापक स्वच्छता अभियान आयोजित किया। स्वयंसेवकों ने कचरा इकट्ठा किया, सार्वजनिक स्थानों की सफ़ाई की, और निवासियों को उचित कचरा निपटान व रीसाइक्लिंग के बारे में जानकारी दी।"}'::jsonb, '2026-03-22', '{"en":"Sectors 8-12, Community Area","hi":"सेक्टर 8-12, सामुदायिक क्षेत्र"}'::jsonb, 'community', '["/assets/images/community-support.jpg"]'::jsonb, 35, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('awareness-campaign-001', '{"en":"Health & Hygiene Awareness","hi":"स्वास्थ्य और स्वच्छता जागरूकता"}'::jsonb, '{"en":"Conducted awareness sessions on health and hygiene in local schools.","hi":"स्थानीय स्कूलों में स्वास्थ्य और स्वच्छता पर जागरूकता सत्र आयोजित किए।"}'::jsonb, '{"en":"Our awareness team visited local schools to conduct interactive sessions on health and hygiene practices. Children learned about handwashing, clean drinking water, nutrition, and basic health habits through fun activities.","hi":"हमारी जागरूकता टीम स्थानीय स्कूलों में स्वास्थ्य और स्वच्छता पर इंटरैक्टिव सत्र आयोजित करने गई। बच्चों ने मज़ेदार गतिविधियों के माध्यम से हाथ धोना, साफ़ पीने का पानी, पोषण और बुनियादी स्वास्थ्य आदतों के बारे में सीखा।"}'::jsonb, '2026-02-05', '{"en":"Government Primary School","hi":"सरकारी प्राथमिक विद्यालय"}'::jsonb, 'awareness', '["/assets/images/awareness.jpg"]'::jsonb, 12, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('community-event-001', '{"en":"Republic Day Seva","hi":"गणतंत्र दिवस सेवा"}'::jsonb, '{"en":"Organized special food distribution and flag hoisting on Republic Day.","hi":"गणतंत्र दिवस पर विशेष भोजन वितरण और ध्वजारोहण आयोजित किया।"}'::jsonb, '{"en":"On Republic Day, we combined patriotism with seva. The day began with a flag hoisting ceremony followed by a large food distribution drive. We served meals to over 200 people and distributed sweets to children.","hi":"गणतंत्र दिवस पर हमने देशभक्ति को सेवा के साथ जोड़ा। दिन की शुरुआत ध्वजारोहण से हुई, इसके बाद बड़े पैमाने पर भोजन वितरण हुआ। हमने 200 से अधिक लोगों को भोजन परोसा और बच्चों में मिठाई बाँटी।"}'::jsonb, '2026-01-26', '{"en":"Main Community Ground","hi":"मुख्य सामुदायिक मैदान"}'::jsonb, 'events', '["/assets/images/community-support.jpg"]'::jsonb, 50, true) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('bird-care-001', '{"en":"Bird Water Bowl Initiative","hi":"पक्षियों के लिए जल कटोरा पहल"}'::jsonb, '{"en":"Installed water bowls across the city for birds during extreme heat.","hi":"तेज़ गर्मी में पक्षियों के लिए पूरे शहर में पानी के कटोरे लगाए।"}'::jsonb, '{"en":"During extreme summer temperatures, birds struggle to find water. Our volunteers placed clay water bowls at parks, bus stops, and residential areas to provide relief to birds. Community members were encouraged to refill and maintain the bowls.","hi":"चरम गर्मी में पक्षियों के लिए पानी ढूँढना मुश्किल हो जाता है। हमारे स्वयंसेवकों ने पार्कों, बस स्टॉपों और आवासीय क्षेत्रों में मिट्टी के जल-कटोरे रखे ताकि पक्षियों को राहत मिले। समुदाय के सदस्यों को इन कटोरों को भरने और देखभाल के लिए प्रेरित किया गया।"}'::jsonb, '2026-05-15', '{"en":"Citywide Initiative","hi":"पूरे शहर में पहल"}'::jsonb, 'animals', '["/assets/images/animal-care.jpg"]'::jsonb, 30, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('green-campaign-001', '{"en":"River Clean-Up Campaign","hi":"नदी सफ़ाई अभियान"}'::jsonb, '{"en":"Organized a river bank clean-up with over 50 volunteers joining hands.","hi":"50 से अधिक स्वयंसेवकों के साथ नदी तट सफ़ाई अभियान आयोजित किया।"}'::jsonb, '{"en":"We organized a massive river bank clean-up campaign. Over 50 volunteers spent the entire day collecting waste, plastic, and debris from the river bank. The initiative aimed to restore the natural beauty of the water body and raise awareness about water pollution.","hi":"हमने एक विशाल नदी तट सफ़ाई अभियान आयोजित किया। 50 से अधिक स्वयंसेवकों ने पूरे दिन नदी तट से कचरा, प्लास्टिक और मलबा हटाया। इस पहल का उद्देश्य जलस्रोत की प्राकृतिक सुंदरता को पुनःस्थापित करना और जल प्रदूषण के प्रति जागरूकता बढ़ाना था।"}'::jsonb, '2026-04-22', '{"en":"Local River Bank","hi":"स्थानीय नदी तट"}'::jsonb, 'nature', '["/assets/images/nature-seva.jpg"]'::jsonb, 55, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('elderly-support-001', '{"en":"Elderly Care Visit","hi":"वृद्धाश्रम देखभाल भेंट"}'::jsonb, '{"en":"Visited old age home and spent time with residents, providing supplies.","hi":"वृद्धाश्रम गए, निवासियों के साथ समय बिताया और आवश्यक सामग्री दी।"}'::jsonb, '{"en":"Our volunteers visited a local old age home with essential supplies, fruits, and warm companionship. We spent time talking, singing, and sharing stories with the residents. Many of our volunteers said it was the most moving experience of their lives.","hi":"हमारे स्वयंसेवक आवश्यक सामग्री, फल और गर्मजोशी भरी संगत के साथ स्थानीय वृद्धाश्रम गए। हमने निवासियों के साथ बातें की, गाने गाए और कहानियाँ साझा कीं। हमारे कई स्वयंसेवकों ने कहा कि यह उनके जीवन का सबसे भावुक अनुभव था।"}'::jsonb, '2026-03-08', '{"en":"Local Old Age Home","hi":"स्थानीय वृद्धाश्रम"}'::jsonb, 'community', '["/assets/images/community-support.jpg"]'::jsonb, 18, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('education-seva-001', '{"en":"Books & Stationery Distribution","hi":"पुस्तक व स्टेशनरी वितरण"}'::jsonb, '{"en":"Distributed school supplies to underprivileged children.","hi":"वंचित बच्चों में स्कूली सामग्री वितरित की।"}'::jsonb, '{"en":"We distributed notebooks, pencils, crayons, and school bags to underprivileged children in our community. Every child deserves the tools to learn and grow, and this initiative was our small contribution to their education.","hi":"हमने समुदाय के वंचित बच्चों में कॉपियाँ, पेंसिल, क्रेयॉन और स्कूल बैग वितरित किए। हर बच्चे को सीखने और बढ़ने के साधन मिलने चाहिए, और यह पहल उनकी शिक्षा के लिए हमारा छोटा योगदान थी।"}'::jsonb, '2026-06-01', '{"en":"Community Center","hi":"सामुदायिक केंद्र"}'::jsonb, 'community', '["/assets/images/community-support.jpg"]'::jsonb, 22, null) on conflict (id) do nothing;
insert into public.activities (id, title, description, "longDescription", date, location, category, images, "volunteersInvolved", featured) values ('environment-day-001', '{"en":"World Environment Day Celebration","hi":"विश्व पर्यावरण दिवस समारोह"}'::jsonb, '{"en":"Organized tree plantation and environment awareness program.","hi":"वृक्षारोपण और पर्यावरण जागरूकता कार्यक्रम आयोजित किया।"}'::jsonb, '{"en":"On World Environment Day, we organized a special program that combined tree plantation with environmental awareness. We planted 100 trees, conducted a nature walk, and held a poster-making competition for children on environmental themes.","hi":"विश्व पर्यावरण दिवस पर हमने वृक्षारोपण और पर्यावरण जागरूकता को जोड़ने वाला एक विशेष कार्यक्रम आयोजित किया। हमने 100 पेड़ लगाए, प्रकृति प्रवास आयोजित किया और बच्चों के लिए पर्यावरण विषयों पर पोस्टर-निर्माण प्रतियोगिता रखी।"}'::jsonb, '2026-06-05', '{"en":"Community Park","hi":"सामुदायिक पार्क"}'::jsonb, 'events', '["/assets/images/nature-seva.jpg"]'::jsonb, 45, null) on conflict (id) do nothing;
insert into public.seva_categories (id, title, description, "longDescription", icon, image, activities) values ('dana-pani', '{"en":"Dana Pani","hi":"दाना पानी"}'::jsonb, '{"en":"Providing food and water to people and animals who need it.","hi":"ज़रूरतमंद लोगों और पशु-पक्षियों को भोजन और जल उपलब्ध कराना।"}'::jsonb, '{"en":"Dana Pani Seva is at the heart of our mission. We believe that no person or animal should go hungry. Our volunteers regularly distribute meals, drinking water, and basic food supplies to those in need — from street vendors and daily wage workers to stray animals suffering in the heat.","hi":"दाना पानी सेवा हमारे मिशन के केंद्र में है। हमारा मानना है कि कोई भी इंसान या जानवर भूखा न रहे। हमारे स्वयंसेवक नियमित रूप से ज़रूरतमंदों को भोजन, पीने का पानी और बुनियादी राशन वितरित करते हैं — रेहड़ी-पटरी वालों और दिहाड़ी मज़दूरों से लेकर गर्मी में तड़पते आवारा जानवरों तक।"}'::jsonb, 'utensils', '/assets/images/food-seva.jpg', '[{"en":"Meal distribution in localities","hi":"मोहल्लों में भोजन वितरण"},{"en":"Water distribution during summer","hi":"गर्मियों में जल वितरण"},{"en":"Food packets for daily wage workers","hi":"दिहाड़ी मज़दूरों के लिए राशन पैकेट"},{"en":"Feeding stray animals","hi":"आवारा पशुओं को भोजन"}]'::jsonb) on conflict (id) do nothing;
insert into public.seva_categories (id, title, description, "longDescription", icon, image, activities) values ('nature-seva', '{"en":"Nature Seva","hi":"प्रकृति सेवा"}'::jsonb, '{"en":"Working towards a cleaner, greener and healthier environment.","hi":"स्वच्छ, हरित और स्वस्थ पर्यावरण की दिशा में कार्य।"}'::jsonb, '{"en":"Nature Seva focuses on creating a cleaner and greener environment for everyone. Through tree plantations, cleanliness drives, and environmental awareness campaigns, we work to protect and restore the natural world around us.","hi":"प्रकृति सेवा सबके लिए स्वच्छ और हरित पर्यावरण बनाने पर केंद्रित है। वृक्षारोपण, स्वच्छता अभियानों और पर्यावरण जागरूकता अभियानों के माध्यम से हम अपने आस-पास की प्राकृतिक दुनिया की रक्षा और पुनर्स्थापन का कार्य करते हैं।"}'::jsonb, 'leaf', '/assets/images/nature-seva.jpg', '[{"en":"Tree plantation drives","hi":"वृक्षारोपण अभियान"},{"en":"Neighborhood cleanliness campaigns","hi":"मोहल्ला स्वच्छता अभियान"},{"en":"River and lake clean-up","hi":"नदी और झील सफ़ाई"},{"en":"Environmental awareness programs","hi":"पर्यावरण जागरूकता कार्यक्रम"}]'::jsonb) on conflict (id) do nothing;
insert into public.seva_categories (id, title, description, "longDescription", icon, image, activities) values ('community-support', '{"en":"Community Support","hi":"सामुदायिक सहायता"}'::jsonb, '{"en":"Helping people through small but meaningful acts of kindness.","hi":"छोटे पर सार्थक दयालुता के कामों से लोगों की मदद।"}'::jsonb, '{"en":"Our Community Support initiatives focus on helping individuals and families facing difficult times. From distributing essential supplies to organizing support for the elderly and underprivileged, we aim to strengthen the fabric of our community through compassion.","hi":"हमारी सामुदायिक सहायता पहलें मुश्किल दौर से गुज़र रहे लोगों और परिवारों की मदद पर केंद्रित हैं। आवश्यक सामग्री वितरण से लेकर वृद्धों और वंचितों के लिए सहायता आयोजन तक — हम करुणा के माध्यम से समुदाय का ताना-बाना मज़बूत करना चाहते हैं।"}'::jsonb, 'heart-handshake', '/assets/images/community-support.jpg', '[{"en":"Essential supply distribution","hi":"आवश्यक सामग्री वितरण"},{"en":"Support for elderly citizens","hi":"वरिष्ठ नागरिकों की सहायता"},{"en":"Helping families in need","hi":"ज़रूरतमंद परिवारों की मदद"},{"en":"Community gathering and support","hi":"सामुदायिक मेलजोल और सहयोग"}]'::jsonb) on conflict (id) do nothing;
insert into public.seva_categories (id, title, description, "longDescription", icon, image, activities) values ('animal-care', '{"en":"Animal & Bird Care","hi":"पशु-पक्षी सेवा"}'::jsonb, '{"en":"Providing food and water and caring for animals and birds.","hi":"पशु-पक्षियों को भोजन, जल और देखभाल उपलब्ध कराना।"}'::jsonb, '{"en":"Every living being deserves care. Our Animal & Bird Care initiative provides food, water, and basic medical support to stray animals and birds. From setting up water bowls in summer to feeding stray dogs and cats, we work to make our neighborhoods safer for all creatures.","hi":"हर जीव देखभाल का हक़दार है। हमारी पशु-पक्षी सेवा पहल आवारा जानवरों और पक्षियों को भोजन, पानी और बुनियादी चिकित्सा सहायता उपलब्ध कराती है। गर्मियों में पानी के कटोरे लगाने से लेकर आवारा कुत्तों-बिल्लियों को खिलाने तक — हम हर प्राणी के लिए अपने मोहल्ले को सुरक्षित बनाने का प्रयास करते हैं।"}'::jsonb, 'paw-print', '/assets/images/animal-care.jpg', '[{"en":"Feeding stray animals","hi":"आवारा पशुओं को भोजन"},{"en":"Setting up water bowls for birds","hi":"पक्षियों के लिए जल कटोरे"},{"en":"Animal awareness campaigns","hi":"पशु जागरूकता अभियान"},{"en":"Collaborating with local shelters","hi":"स्थानीय आश्रयों के साथ सहयोग"}]'::jsonb) on conflict (id) do nothing;
insert into public.seva_categories (id, title, description, "longDescription", icon, image, activities) values ('awareness', '{"en":"Awareness","hi":"जागरूकता"}'::jsonb, '{"en":"Encouraging people to participate in social and environmental activities.","hi":"सामाजिक और पर्यावरणीय गतिविधियों में भाग लेने के लिए प्रेरित करना।"}'::jsonb, '{"en":"Spreading awareness is a powerful form of seva. We organize and participate in campaigns that educate people about social issues, environmental conservation, health, hygiene, and the importance of community service. Every person we inspire becomes a carrier of positive change.","hi":"जागरूकता फैलाना सेवा का एक शक्तिशाली रूप है। हम ऐसे अभियानों का आयोजन करते हैं और उनमें भाग लेते हैं जो लोगों को सामाजिक मुद्दों, पर्यावरण संरक्षण, स्वास्थ्य, स्वच्छता और सामुदायिक सेवा के महत्व के बारे में शिक्षित करते हैं। हमारे द्वारा प्रेरित हर व्यक्ति सकारात्मक बदलाव का वाहक बन जाता है।"}'::jsonb, 'megaphone', '/assets/images/awareness.jpg', '[{"en":"Social awareness campaigns","hi":"सामाजिक जागरूकता अभियान"},{"en":"Health and hygiene drives","hi":"स्वास्थ्य और स्वच्छता अभियान"},{"en":"Environmental education","hi":"पर्यावरण शिक्षा"},{"en":"Volunteer recruitment drives","hi":"स्वयंसेवक भर्ती अभियान"}]'::jsonb) on conflict (id) do nothing;
